WITH valid AS (SELECT *, CAST(temp_c AS INT) AS temp_c_int FROM device_readings WHERE status_bits < 10), prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM valid), with_gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM prev_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_no, CASE WHEN pressure >= 1031 THEN 'PREMIUM' ELSE 'STANDARD' END AS pressure_tier, BIT_OR(status_bits) AS status_bits_bit_or, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min FROM islands GROUP BY session_no, pressure_tier ORDER BY session_no DESC
